function bodyThickness(z,index,total,widthMul=1,source=0){const progress=index/(total-1),tailFactor=1-.62*Math.pow(progress,10),neck=source<1.5?endpoint.neckWidth+(1-endpoint.neckWidth)*clamp(source/1.5,0,1):1;return .34*currentScale()*depthScale(z)*tailFactor*clamp(widthMul,.2,3)*neck;}
