function isBehindEarth(p,width){const idx=nearestControlIndex(p.source??0),override=pts[idx].earth;if(override==="FRONT_OF_EARTH")return false;if(override==="BEHIND_EARTH")return true;const front=earthFrontDepth(p.x,p.y);if(front===null)return false;const bodyRadiusWorld=(width/currentScale())*.36;return p.z+bodyRadiusWorld<front;}

function segmentIntersection(a,b,c,d){const r={x:b.x-a.x,y:b.y-a.y},s={x:d.x-c.x,y:d.y-c.y},den=r.x*s.y-r.y*s.x;if(Math.abs(den)<1e-6)return null;const q={x:c.x-a.x,y:c.y-a.y},t=(q.x*s.y-q.y*s.x)/den,u=(q.x*r.y-q.y*r.x)/den;if(t<=.02||t>=.98||u<=.02||u>=.98)return null;return{x:a.x+r.x*t,y:a.y+r.y*t,t,u};}
