function draw(){ctx.clearRect(0,0,W,H);drawStars();drawReferenceCircle();drawMoon(true);drawEarth();drawMoon(false);drawContactShadows();const screen=classify(sampleCurve());drawSnake(screen);drawDirectionArrows(screen);drawHead(screen);drawTail(screen);drawGazeSparkles(screen);drawMouthTailGuide();drawClosurePreview();drawTopologyMarkers(screen);drawPoints();}

function nearestPoint(x,y,maxRadius=null){let best=-1,bestD=Infinity;pts.forEach((p,i)=>{const s=project(p),dx=s.x-x,dy=s.y-y,d=dx*dx+dy*dy;if(d<bestD){bestD=d;best=i;}});const hit=maxRadius??Math.max(24,30*clamp(viewZoom,.8,1.5));return bestD<hit*hit?best:-1;}
function nearestCurveLocation(x,y,maxDist=26){const samples=sampleCurve();let best=null,bestD=Infinity;for(let i=0;i<samples.length-1;i++){const a=project(samples[i]),b=project(samples[i+1]),vx=b.x-a.x,vy=b.y-a.y,L2=vx*vx+vy*vy;if(L2<1e-6)continue;const t=clamp(((x-a.x)*vx+(y-a.y)*vy)/L2,0,1),px=a.x+vx*t,py=a.y+vy*t,d=Math.hypot(x-px,y-py);if(d<bestD){bestD=d;best={x:lerp(samples[i].x,samples[i+1].x,t),y:lerp(samples[i].y,samples[i+1].y,t),z:lerp(samples[i].z,samples[i+1].z,t),width:lerp(samples[i].width,samples[i+1].width,t),source:lerp(samples[i].source,samples[i+1].source,t),screenX:px,screenY:py,distance:d};}}return bestD<=maxDist?best:null;}
function hitEarth(x,y){const s=currentScale(),ex=cx+viewX+earth.x*s,ey=cy+viewY-earth.y*s,r=earthApparentRadius()*s;return Math.hypot(x-ex,y-ey)<=r;}

function parseCrossingKey(key){const parts=String(key).split(":").map(Number),[a,b,ordinal]=parts;return Number.isFinite(a)&&Number.isFinite(b)?[a,b,Number.isFinite(ordinal)?ordinal:null]:null;}
function remapCrossingsOnInsert(index){const next={};for(const[key,val]of Object.entries(crossingOverrides)){const pair=parseCrossingKey(key);if(!pair)continue;let[a,b,ordinal]=pair;const split=index-1;if(a===split||b===split)continue;if(a>=index)a++;if(b>=index)b++;next[crossingKey(a,b,ordinal)]=val;}crossingOverrides=next;}
function remapCrossingsOnDelete(index){const next={};for(const[key,val]of Object.entries(crossingOverrides)){const pair=parseCrossingKey(key);if(!pair)continue;let[a,b,ordinal]=pair;if(a===index-1||a===index||b===index-1||b===index)continue;if(a>index)a--;if(b>index)b--;next[crossingKey(a,b,ordinal)]=val;}crossingOverrides=next;}
function insertPointAtLocation(loc){if(!loc)return -1;const span=clamp(Math.floor(loc.source),0,pts.length-2),index=span+1,a=pts[span],b=pts[span+1];remapCrossingsOnInsert(index);pts.splice(index,0,{x:loc.x,y:loc.y,z:clamp(loc.z,0,14),width:clamp(loc.width,.2,3),earth:a.earth===b.earth?a.earth:"AUTO",contact:a.contact===b.contact?a.contact:"AUTO"});selected=index;if(preserveLength)preserveTarget=arcLength();return index;}
function insertAtSource(source){return insertPointAtLocation(curvePointAtSource(clamp(source,.001,pts.length-1.001)));}
function deleteSelectedPoint(){if(selected<=0||selected>=pts.length-1||pts.length<=7)return false;const index=selected;remapCrossingsOnDelete(index);pts.splice(index,1);selected=Math.min(index,pts.length-2);if(preserveLength)preserveTarget=arcLength();return true;}
function duplicateSelectedPoint(){if(selected<0)return false;const src=pts[selected],index=Math.min(selected+1,pts.length-1);remapCrossingsOnInsert(index);pts.splice(index,0,{...clone(src),x:src.x+.08,y:src.y+.08});selected=index;if(preserveLength)preserveTarget=arcLength();return true;}

