const rangeEdits=new Map();
function rangePrecision(el){const step=String(el.step||"1");return step.includes(".")?step.split(".")[1].length:0;}
function normalizeRangeValue(el,v){const min=Number.isFinite(+el.min)?+el.min:-Infinity,max=Number.isFinite(+el.max)?+el.max:Infinity,step=+el.step||1;v=clamp(+v,min,max);if(Number.isFinite(min)){const n=Math.round((v-min)/step);v=min+n*step;}return +v.toFixed(Math.max(rangePrecision(el),4));}
function applyRange(id,v){const el=$(id),cfg=rangeConfigs[id];if(!el||!cfg||el.disabled)return;v=normalizeRangeValue(el,v);el.value=v;cfg.apply(v);syncAllUI();draw();if(cfg.history===false)scheduleAutosave();}
function armRange(el){const cfg=rangeConfigs[el.id];if(!cfg||cfg.history===false||rangeEdits.has(el))return;rangeEdits.set(el,sceneState());}
function finishRange(el){const cfg=rangeConfigs[el.id],before=rangeEdits.get(el);if(before&&cfg?.history!==false)commit(before);rangeEdits.delete(el);syncAllUI();}
function installTaskControls(){const body=$("sheetBody");if(!body)return;if(!$("constraintControls")){const section=document.createElement("div");section.id="constraintControls";section.className="section";section.innerHTML=`<div class="sectionTitle">Ouroboros state</div><div class="twoCol"><button id="biteTailBtn" type="button">Bite tail</button><button id="releaseTailBtn" type="button">Release tail</button></div><div class="controlRow readOnlyRow"><label>Length</label><button id="preserveLengthToggle" type="button">Free length</button></div><div class="subtle" id="preserveLengthValue">head/tail only</div>`;const firstSection=body.querySelector(".section");body.insertBefore(section,firstSection||body.firstChild);$("biteTailBtn").onclick=()=>setBiteState(true);$("releaseTailBtn").onclick=()=>setBiteState(false);$("preserveLengthToggle").onclick=()=>setPreserveLength(!preserveLength);}
if(!$("gazeStarsToggle")){const grid=$("gazeArrow")?.parentElement;if(grid){const btn=document.createElement("button");btn.id="gazeStarsToggle";btn.type="button";btn.textContent="Gaze stars";grid.appendChild(btn);btn.onclick=()=>mutate(()=>display.gazeStars=!display.gazeStars);}}
if(!$("gazeOpacity")){const guide=$("gazeArrow")?.closest(".section");if(guide){const row=document.createElement("div");row.className="controlRow";row.innerHTML=`<label>Gaze opacity</label><input id="gazeOpacity" type="range" min="0" max="1" step=".05" value="${display.gazeOpacity}"><div class="controlValue" id="gazeOpacityValue">${display.gazeOpacity.toFixed(2)}</div>`;guide.appendChild(row);}}
if(!$("depthFog")){const light=$("lightToggle")?.closest(".section");if(light){const row=document.createElement("div");row.className="controlRow";row.innerHTML=`<label>Depth fog</label><input id="depthFog" type="range" min="0" max=".5" step=".02" value="${lighting.depthFog}"><div class="controlValue" id="depthFogValue">${lighting.depthFog.toFixed(2)}</div>`;light.appendChild(row);}}
}
function enhanceNumericControls(){for(const el of document.querySelectorAll('input[type="range"]')){const row=el.closest(".controlRow");if(!row||!rangeConfigs[el.id])continue;row.classList.add("numericRow");const minus=document.createElement("button"),plus=document.createElement("button"),num=document.createElement("input");minus.type=plus.type="button";minus.textContent="−";plus.textContent="+";minus.className=plus.className="stepBtn";minus.setAttribute("aria-label",`Decrease ${el.id}`);plus.setAttribute("aria-label",`Increase ${el.id}`);num.type="number";num.className="numericInput";num.inputMode="decimal";num.min=el.min;num.max=el.max;num.step=el.step;num.value=el.value;num.setAttribute("aria-label",`Exact value for ${el.id}`);row.insertBefore(minus,el);const oldValue=row.querySelector(".controlValue");row.insertBefore(plus,oldValue);row.insertBefore(num,oldValue);
el.addEventListener("pointerdown",()=>armRange(el));el.addEventListener("keydown",()=>armRange(el));el.addEventListener("input",()=>applyRange(el.id,+el.value));el.addEventListener("change",()=>{applyRange(el.id,+el.value);finishRange(el);});el.addEventListener("pointerup",()=>finishRange(el));el.addEventListener("pointercancel",()=>finishRange(el));
let numBefore=null;num.addEventListener("focus",()=>{if(rangeConfigs[el.id].history!==false)numBefore=sceneState();});num.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();num.blur();}});num.addEventListener("change",()=>{const v=Number(num.value);if(Number.isFinite(v))applyRange(el.id,v);else num.value=el.value;if(numBefore){commit(numBefore);numBefore=null;}syncAllUI();});num.addEventListener("blur",()=>{if(numBefore){const v=Number(num.value);if(Number.isFinite(v))applyRange(el.id,v);commit(numBefore);numBefore=null;}syncAllUI();});
for(const[btn,dir]of[[minus,-1],[plus,1]]){let before=null,timer=0,interval=0,active=false;const stepOnce=()=>applyRange(el.id,+el.value+dir*(+el.step||1));const end=()=>{if(!active)return;active=false;clearTimeout(timer);clearInterval(interval);if(before){commit(before);before=null;}syncAllUI();};btn.addEventListener("pointerdown",e=>{if(el.disabled)return;e.preventDefault();active=true;if(rangeConfigs[el.id].history!==false)before=sceneState();stepOnce();timer=setTimeout(()=>{interval=setInterval(stepOnce,85);},360);btn.setPointerCapture?.(e.pointerId);});btn.addEventListener("pointerup",end);btn.addEventListener("pointercancel",end);btn.addEventListener("lostpointercapture",end);}
}}

