$("flipCrossing").onclick=()=>{const list=currentCrossings();if(!list.length)return;const c=list[currentCrossing%list.length];mutate(()=>{const v=crossingOverrides[c.key];crossingOverrides[c.key]=(v==="LOW_FRONT"||v==="A_FRONT")?"HIGH_FRONT":(v==="HIGH_FRONT"||v==="B_FRONT")?undefined:"LOW_FRONT";if(!crossingOverrides[c.key])delete crossingOverrides[c.key];});};

