function showCheckpoints(){$("overlay").style.display="flex";$("overlayTitle").textContent="Checkpoints";$("snapshotImage").style.display="none";$("jsonBox").style.display="none";$("checkpointBox").style.display="block";$("copyOverlay").style.display="none";$("applyImport").style.display="none";const box=$("checkpointBox");box.className="";box.innerHTML="";const names=Object.keys(checkpoints);if(!names.length){box.textContent="No checkpoints saved.";return;}for(const name of names){const row=document.createElement("div");row.className="checkpointRow";const label=document.createElement("span");label.textContent=name;const load=document.createElement("button");load.textContent="Load";load.onclick=()=>{const before=sceneState();applyScene(checkpoints[name]);commit(before);$("overlay").style.display="none";};const del=document.createElement("button");del.textContent="Delete";del.onclick=()=>{delete checkpoints[name];autosave();showCheckpoints();};row.append(label,load,del);box.appendChild(row);}}
