function showGestureHelp(){$("overlay").style.display="flex";$("overlayTitle").textContent="Controls & gestures";$("snapshotImage").style.display="none";$("jsonBox").style.display="none";$("checkpointBox").style.display="block";$("copyOverlay").style.display="none";$("applyImport").style.display="none";const box=$("checkpointBox");box.className="helpText";box.innerHTML=`<p><b>Edit:</b> tap/click a point to select; drag it to pose. Tap unobstructed sky to clear selection and collapse the docked controls. Long-press a snake segment or double-click it to add a point. Long-press/right-click a point for point actions.</p><p><b>Move:</b> drag to move only the snake. <b>Pan:</b> drag to move only the viewport. When Earth is unlocked, drag Earth in Edit mode to move Earth and Moon.</p><p><b>Touch:</b> two fingers pan and pinch-zoom at the same time. <b>Mouse/trackpad:</b> wheel zooms around the pointer; Shift+wheel pans; middle-drag or Space+drag temporarily pans.</p><p><b>Ouroboros:</b> Bite tail closes/links the endpoints. Release tail frees them. Preserve length applies only to HEAD/TAIL dragging and uses bounded local correction.</p><p><b>Keyboard:</b> E Edit, M Move, P Pan, arrow keys nudge the selected point (Shift = larger step), Cmd/Ctrl+Z Undo, Cmd/Ctrl+Shift+Z or Cmd/Ctrl+Y Redo, Delete/Backspace removes an eligible body point, +/- zoom, Esc closes menus.</p><p><b>Numbers:</b> X, Y and every slider have − / + and an exact-value field. Hold − or + to repeat.</p>`;}
$("gestureHelp").onclick=showGestureHelp;$("closeOverlay").onclick=()=>$("overlay").style.display="none";

